// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(actor.code.length == 0);
        amount = bound(amount, 0, address(this).balance);
        vm.deal(actor, amount);

        // first guarded call: deposit (succeeds in both P and M)
        vm.prank(actor);
        c.addToBalance{value: amount}();

        // the actor's first withdrawal must succeed and zero the balance
        vm.prank(actor);
        bool ok;
        try c.withdrawBalance() { ok = true; } catch { ok = false; }

        assertTrue(ok && c.getBalance(actor) == 0);
    }
}
